        b.step(1)?;
        if finite.meets(&group.bounds, b)? && !rows.contains(*owner, b)? {
            log_cost(frame.owners.len(), b)?;
            b.retain(6)?;
            frame.members += 6;
            frame.owners.insert(*owner, Vec::new());
        }
    }
    let mut barriers = Vec::new();
    let mut coplanar = Vec::new();
    b.state([
        frame.members,
        frame.owners.len(),
        barriers.len(),
        coplanar.len(),
        originals.len(),
        0,
        0,
        0,
    ]);
